import { airportGroups, airportGroupDescriptions } from '../data/airportGroups';

/**
 * Check if a flight passes the group filter criteria
 */
export const passesGroupFilter = (route, groupFilters) => {
  if (!Object.keys(groupFilters).length) return true;

  // Check each filter group
  for (const filterId in groupFilters) {
    const filter = groupFilters[filterId];
    const [origin, dest] = route.split('-');

    // Check origin filter
    if (filter.originFilter?.mode === 'group' && filter.originFilter?.group) {
      const group = filter.originFilter.group;

      // Include mode: origin must be in the group
      if (filter.originFilter.include) {
        if (!airportGroups[group]?.includes(origin)) return false;
      }
      // Exclude mode: origin must NOT be in the group  
      else {
        if (airportGroups[group]?.includes(origin)) return false;
      }
    }
    // Check single airport origin filter
    else if (filter.originFilter?.mode === 'airport' && filter.originFilter?.airport) {
      const filterAirport = filter.originFilter.airport;

      // Include mode: origin must match airport
      if (filter.originFilter.include) {
        if (origin !== filterAirport) return false;
      }
      // Exclude mode: origin must NOT match airport  
      else {
        if (origin === filterAirport) return false;
      }
    }

    // Check destination filter
    if (filter.destFilter?.mode === 'group' && filter.destFilter?.group) {
      const group = filter.destFilter.group;

      // Include mode: destination must be in the group
      if (filter.destFilter.include) {
        if (!airportGroups[group]?.includes(dest)) return false;
      }
      // Exclude mode: destination must NOT be in the group  
      else {
        if (airportGroups[group]?.includes(dest)) return false;
      }
    }
    // Check single airport destination filter
    else if (filter.destFilter?.mode === 'airport' && filter.destFilter?.airport) {
      const filterAirport = filter.destFilter.airport;

      // Include mode: destination must match airport
      if (filter.destFilter.include) {
        if (dest !== filterAirport) return false;
      }
      // Exclude mode: destination must NOT match airport  
      else {
        if (dest === filterAirport) return false;
      }
    }
  }

  // Passed all filter groups
  return true;
};

/**
 * Check if a flight passes segment filter criteria
 */
export const passesSegmentFilter = (route, segmentFilter, segmentFilters) => {
  // Check main segment filter
  if (segmentFilter?.segments?.length > 0) {
    const included = segmentFilter.segments.includes(route);

    if (segmentFilter.mode === 'include' && !included) return false;
    if (segmentFilter.mode === 'exclude' && included) return false;
  }

  // Check additional segment filters
  for (const filterId in segmentFilters) {
    const filter = segmentFilters[filterId];

    if (filter?.segments?.length > 0) {
      const included = filter.segments.includes(route);

      if (filter.mode === 'include' && !included) return false;
      if (filter.mode === 'exclude' && included) return false;
    }
  }

  return true;
};

/**
 * Get available filter group options
 */
export const getGroupFilterOptions = (airports) => {
  const options = [];

  // Add airport groups
  Object.keys(airportGroups).forEach(groupKey => {
    options.push({
      value: groupKey,
      label: `${groupKey} - ${airportGroupDescriptions[groupKey] || groupKey}`,
      type: 'group'
    });
  });

  // Add individual airports
  if (airports) {
    Object.keys(airports).forEach(code => {
      const airport = airports[code];
      options.push({
        value: code,
        label: `${code} - ${airport.city || ''} ${airport.name || ''}`,
        type: 'airport'
      });
    });
  }

  // Sort options
  return options.sort((a, b) => {
    // Groups first, then airports
    if (a.type !== b.type) {
      return a.type === 'group' ? -1 : 1;
    }
    // Alphabetical by value
    return a.value.localeCompare(b.value);
  });
};

/**
 * Delete a filter by ID
 */
export const deleteFilter = (filterId, additionalFilters, setAdditionalFilters, groupFilters, setGroupFilters, segmentFilters, setSegmentFilters) => {
  // Remove from additionalFilters array
  const updatedFilters = additionalFilters.filter(filter => filter.id !== filterId);
  setAdditionalFilters(updatedFilters);

  // Remove from groupFilters if exists
  if (groupFilters[filterId]) {
    const updatedGroupFilters = { ...groupFilters };
    delete updatedGroupFilters[filterId];
    setGroupFilters(updatedGroupFilters);
  }

  // Remove from segmentFilters if exists
  if (segmentFilters[filterId]) {
    const updatedSegmentFilters = { ...segmentFilters };
    delete updatedSegmentFilters[filterId];
    setSegmentFilters(updatedSegmentFilters);
  }
};
